import React, { useEffect, useState, useMemo, useRef, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import { round } from 'lodash';
import { getCommandHistory } from 'Screens/Contextualization/Dashboard/actions/Actions';
import { selectCommandHistory, selectCommandHistoryHasMore, selectIsLoadingState } from 'store/Dashboard/selectors';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import DateFormatter from 'Common/Components/DateFormatter';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import {
  Wrapper,
  CommandIcon,
  Empty,
  ContentWrapper,
  WrapperCommand,
  Target,
  Footer,
  Author,
  Duration,
  Dark,
  Light,
  Time,
  DotsLoader,
  Dot,
  Sentinel
} from './styled';
import TitleWrapper from '../components/TitleWrapper';

const LOAD_MORE_OFFSET = 40;

const getDuration = (duration) => {
  const value = round(Number(duration), 2);
  return Number.isFinite(value) ? `${value}s` : '—';
};

const CommandHistoryWidget = () => {
  const dispatch = useDispatch();
  const history = useSelector(selectCommandHistory);
  const hasMoreFromServer = useSelector(selectCommandHistoryHasMore);
  const isFetching = useSelector((state) => selectIsLoadingState(state, 'commandHistory'));
  const workspaceSelected = useSelector(selectCurrentWorkspace);

  const [page, setPage] = useState(1);
  const sentinelRef = useRef(null);
  const scrollContainerRef = useRef(null);
  const prevWorkspaceRef = useRef(workspaceSelected);

  const intl = useIntl();
  const translations = useMemo(() => ({
    title: intl.formatMessage({ id: 'dashboard.widgets.commandHistory.title' }),
    empty: intl.formatMessage({ id: 'dashboard.widgets.commandHistory.empty' }),
    runBy: intl.formatMessage({ id: 'dashboard.widgets.commandHistory.runBy' }),
    duration: intl.formatMessage({ id: 'dashboard.widgets.commandHistory.duration' })
  }), [intl]);

  useEffect(() => {
    const workspaceChanged = prevWorkspaceRef.current !== workspaceSelected;
    prevWorkspaceRef.current = workspaceSelected;

    if (workspaceChanged && page !== 1) {
      setPage(1);
      return;
    }

    dispatch(getCommandHistory(page));
  }, [dispatch, page, workspaceSelected]);

  const hasMore = history.length > 0 && hasMoreFromServer;

  const loadMore = useCallback(() => {
    if (!isFetching && hasMore) setPage((p) => p + 1);
  }, [isFetching, hasMore]);

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;
    const observer = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) loadMore(); },
      { root: scrollContainerRef.current, rootMargin: `0px 0px ${LOAD_MORE_OFFSET}px 0px` }
    );
    observer.observe(sentinel);
    return () => observer.disconnect();
  }, [loadMore]);

  if (isFetching && page === 1) return <SpinnerComponent height="250px" />;

  const header = (
    <TitleWrapper
      title={ translations.title }
      icon={ <CommandIcon /> }
    />
  );

  if (!history.length) {
    return (
      <Wrapper>
        {header}
        <Empty>{translations.empty}</Empty>
      </Wrapper>
    );
  }

  return (
    <Wrapper>
      {header}
      <ContentWrapper ref={ scrollContainerRef }>
        {history.map((command, index) => (
          <WrapperCommand key={ `dashboard_command_history_${command._id}_${index}` }>
            <Target title={ `${command.command} ${command.params}` }>
              {command.command} {command.params}
            </Target>
            <Footer>
              <Author>
                <Light>{translations.runBy} </Light>
                <Dark>{command.creator || '—'}</Dark>
              </Author>
              <Duration>
                <Light>{translations.duration} </Light>
                <Dark>{getDuration(command.duration)}</Dark>
              </Duration>
            </Footer>
            <Time>
              <DateFormatter date={ command.metadata.create_time } />
            </Time>
          </WrapperCommand>
        ))}
        {hasMore && <Sentinel ref={ sentinelRef } />}
        {isFetching && page > 1 && (
          <DotsLoader>
            <Dot delay="0s" />
            <Dot delay="0.2s" />
            <Dot delay="0.4s" />
          </DotsLoader>
        )}
      </ContentWrapper>
    </Wrapper>
  );
};

export default CommandHistoryWidget;
